// Reconcile the per-photo face payload used by the estimator UI. Keep this
// separate from the measurement graph: the graph owns billing/deduction
// aggregation, while this view preserves all useful per-face evidence.
const reconcilePhotoFaces = (photoResults = []) => {
  const canonicalFace = (value) => {
    const raw = String(value || '').toLowerCase().trim().replace(/[\s-]+/g, '_');
    if (/(^|_)(fr|front_right|front_left|frontright|frontleft)(_|$)/.test(raw) || /(^|_)front(_|$)/.test(raw)) return 'front';
    if (/(^|_)(br|back_right|back_left|backright|backleft)(_|$)/.test(raw) || /(^|_)(back|rear)(_|$)/.test(raw)) return 'back';
    if (/(^|_)(left|left_side|west)(_|$)/.test(raw)) return 'left';
    if (/(^|_)(right|right_side|east)(_|$)/.test(raw)) return 'right';
    if (/(^|_)south(_|$)/.test(raw)) return 'front';
    if (/(^|_)north(_|$)/.test(raw)) return 'back';
    return 'unknown';
  };
  const openingKey = (opening) => {
    const type = String(opening?.type || 'opening').toLowerCase();
    const id = opening?.observation_id || opening?.id;
    if (id) return `id:${id}`;
    const zone = opening?.zone || opening?.position_label;
    const x = Number(opening?.pos_x), y = Number(opening?.pos_y);
    const width = Number(opening?.width_ft), height = Number(opening?.height_ft);
    if (!zone && (!Number.isFinite(x) || !Number.isFinite(y))) return null;
    return `${type}:${zone || ''}:${Number.isFinite(x) ? x.toFixed(2) : ''}:${Number.isFinite(y) ? y.toFixed(2) : ''}:${Number.isFinite(width) ? width.toFixed(2) : ''}:${Number.isFinite(height) ? height.toFixed(2) : ''}`;
  };
  const faces = {};
  for (const [index, photo] of photoResults.entries()) {
    const face = canonicalFace(photo?.wall_face || photo?.view_label || photo?.label);
    if (face === 'unknown') continue;
    const label = photo?.view_label || photo?.label || face;
    const mapped = (Array.isArray(photo?.openings) ? photo.openings : []).map(opening => ({
      ...opening,
      wall_face: face,
      source_label: label,
    }));
    if (!faces[face]) {
      faces[face] = {
        face,
        photo_label: label,
        photo_labels: [label],
        wall_width_ft: Number(photo?.wall_width_ft) || 0,
        wall_height_ft: Number(photo?.wall_height_ft || photo?.eave_height_ft) || 0,
        story_count: Number(photo?.story_count) || 1,
        openings: mapped,
        siding_material: photo?.siding_material || null,
        has_mixed_materials: !!photo?.has_mixed_materials,
        confidence: Number(photo?.confidence) || 70,
      };
      continue;
    }
    const target = faces[face];
    const seen = new Set(target.openings.map(opening => openingKey(opening)).filter(Boolean));
    for (const opening of mapped) {
      const key = openingKey(opening);
      if (!key || !seen.has(key)) {
        target.openings.push(opening);
        if (key) seen.add(key);
      }
    }
    if (!target.photo_labels.includes(label)) target.photo_labels.push(label);
    if ((Number(photo?.wall_width_ft) || 0) > target.wall_width_ft) {
      target.wall_width_ft = Number(photo.wall_width_ft);
      target.photo_label = label;
    }
    target.has_mixed_materials = target.has_mixed_materials || !!photo?.has_mixed_materials;
    target.confidence = Math.max(target.confidence, Number(photo?.confidence) || 70);
    // Keep the latest observation's height only when the canonical face did
    // not have a usable value yet.
    if (!target.wall_height_ft) target.wall_height_ft = Number(photo?.wall_height_ft || photo?.eave_height_ft) || 0;
    if (!target.story_count) target.story_count = Number(photo?.story_count) || 1;
    void index;
  }
  return ['front', 'back', 'left', 'right'].filter(face => faces[face]).map(face => faces[face]);
};

// ── Shared street-level geometry helpers ────────────────────────────────────
// getStreetViewImages defines local copies for its own aiming pass; these
// module-level versions exist so the siding recapture path can search for an
// alternative panorama without duplicating (or drifting from) that maths.
const geoBearingTo = (lat1, lng1, lat2, lng2) => {
  const dLng = (lng2 - lng1) * Math.PI / 180;
  const p1 = lat1 * Math.PI / 180, p2 = lat2 * Math.PI / 180;
  const y = Math.sin(dLng) * Math.cos(p2);
  const x = Math.cos(p1) * Math.sin(p2) - Math.sin(p1) * Math.cos(p2) * Math.cos(dLng);
  return ((Math.atan2(y, x) * 180 / Math.PI) + 360) % 360;
};

const geoOffsetLatLng = (lat, lng, distM, bearingDeg) => {
  const R = 6371000;
  const b = bearingDeg * Math.PI / 180;
  const lat1 = lat * Math.PI / 180, lng1 = lng * Math.PI / 180;
  const sinLat2 = Math.sin(lat1) * Math.cos(distM / R)
                + Math.cos(lat1) * Math.sin(distM / R) * Math.cos(b);
  const lat2 = Math.asin(sinLat2);
  const lng2 = lng1 + Math.atan2(
    Math.sin(b) * Math.sin(distM / R) * Math.cos(lat1),
    Math.cos(distM / R) - Math.sin(lat1) * sinLat2,
  );
  return { lat: lat2 * 180 / Math.PI, lng: lng2 * 180 / Math.PI };
};

/**
 * Resolve one alternative Street View frame for a wall whose auto-fetched frame
 * was rejected as unmeasurable.
 *
 * The plan (from photoUsabilityGate) says how far from the house to look for a
 * road panorama, and how to re-aim once one is found. Searching from a
 * different distance is what surfaces an ADJACENT panorama; the heading, pitch,
 * and field-of-view offsets re-frame whichever panorama comes back.
 *
 * Returns null when Google has nothing at that search point — the caller then
 * moves on to the next plan without spending a vision call.
 */
async function resolveAlternativeStreetViewFrame({
  apiKey,
  latitude,
  longitude,
  wallAzimuth,
  plan,
}) {
  if (!apiKey || !plan) return null;
  const lat = Number(latitude);
  const lng = Number(longitude);
  if (!Number.isFinite(lat) || !Number.isFinite(lng)) return null;

  // Stand on the far side of the house from the wall we want to see.
  const az = Number.isFinite(Number(wallAzimuth)) ? Number(wallAzimuth) : 0;
  const searchBearing = (az + 180) % 360;
  const pt = geoOffsetLatLng(lat, lng, plan.search_distance_m, searchBearing);

  const metaUrl = `https://maps.googleapis.com/maps/api/streetview/metadata`
    + `?location=${pt.lat},${pt.lng}&radius=${plan.search_radius_m}&source=outdoor&key=${apiKey}`;
  let meta;
  try {
    const resp = await fetch(metaUrl, { signal: AbortSignal.timeout(8000) });
    meta = await resp.json();
  } catch (err) {
    // Network failure or unparseable body. We learned nothing about coverage.
    return { error: err.message, indeterminate: true };
  }
  if (meta?.status !== 'OK' || !meta.pano_id) {
    // ZERO_RESULTS/NOT_FOUND is Google answering "no panorama here" — a real
    // rung of the ladder. REQUEST_DENIED, OVER_QUERY_LIMIT and friends are our
    // problem, not the house's, and must not be read as absence of coverage.
    const indeterminate = photoUsabilityGate.isIndeterminateLookupStatus(meta?.status)
      || (meta?.status === 'OK' && !meta.pano_id);
    return {
      noCoverage: !indeterminate,
      indeterminate,
      status: meta?.status || 'UNKNOWN',
      error: indeterminate ? `Street View metadata returned ${meta?.status || 'an unreadable response'}` : null,
    };
  }

  const panoLat = meta.location?.lat;
  const panoLng = meta.location?.lng;
  const baseHeading = (panoLat != null && panoLng != null)
    ? geoBearingTo(panoLat, panoLng, lat, lng)
    : az;
  const heading = Math.round((((baseHeading + plan.heading_offset_deg) % 360) + 360) % 360);
  const pitch = Math.round(plan.pitch_deg);
  const fov = Math.round(plan.fov_deg);

  return {
    panoId: meta.pano_id,
    heading,
    pitch,
    fov,
    strategy: plan.strategy,
    search_distance_m: plan.search_distance_m,
    imageUrl: `https://maps.googleapis.com/maps/api/streetview?size=640x480`
      + `&pano=${meta.pano_id}&heading=${heading}&fov=${fov}&pitch=${pitch}&key=${apiKey}`,
  };
}

/**
 * Validates a webhook URL against SSRF risks.
 * - Requires https: scheme
 * - Rejects localhost, loopback, link-local, RFC1918 private ranges, and
 *   well-known internal TLDs (.local, .internal, .corp)
 * - DNS-resolves the hostname and re-checks the resolved IP
 * Returns null if valid, or an error string describing the problem.
 */
const _privateIpPattern = /^(127\.|10\.|169\.254\.|0\.)|(^172\.(1[6-9]|2\d|3[01])\.)|(^192\.168\.)/;
const _isPrivateIp = (addr) => {
  if (!addr) return true;
  // Strip IPv6 brackets ([::1] → ::1)
  const a = addr.replace(/^\[|\]$/g, '').toLowerCase();
  if (a === '::1' || a === '0:0:0:0:0:0:0:1' || a === '0000:0000:0000:0000:0000:0000:0000:0001') return true;
  if (a.startsWith('fc') || a.startsWith('fd') || a.startsWith('fe80')) return true;
  return _privateIpPattern.test(a);
};
/**
 * Server-side mirror of resolveStoredRcv() in src/utils/estimateTotals.js.
 *
 * Inlined rather than imported because src/ is not copied into dist/ — importing
 * it here would break production at boot.
 *
 * A saved line item's stored value is the authority. A stored $0 is REAL (carrier
 * -furnished / ITEL supply lines sit at $0 next to a live quantity and rate), so
 * the truthy `rcv || amount || qty * rate` idiom this replaces silently re-priced
 * those lines. That is how one estimate could be worth one number in the editor,
 * another in the export sent to the adjuster, and a third once invoiced.
 */
function resolveStoredRcvServer(item) {
  for (const key of ['rcv', 'amount', 'total', 'subtotal']) {
    const raw = item?.[key];
    if (raw === null || raw === undefined || raw === '') continue;
    const n = Number(raw);
    if (Number.isFinite(n)) return n;
  }
  const qty = Number(item?.quantity ?? item?.qty) || 0;
  const rate = Number(item?.rate ?? item?.price ?? item?.unit_price) || 0;
  return qty * rate;
}

