// ── Staff Scoring Engine ─────────────────────────────────────────────────────
const SCORE_RULES = {
  appointment_created:   { points: 10, desc: 'Appointment booked' },
  appointment_completed: { points: 15, desc: 'Appointment completed' },
  inspection_scheduled:  { points: 10, desc: 'Inspection scheduled' },
  lead_created:          { points: 5,  desc: 'New lead added' },
  lead_status_changed:   { points: 8,  desc: 'Lead moved forward' },
  customer_created:      { points: 5,  desc: 'Customer created' },
  estimate_sent:         { points: 15, desc: 'Estimate sent' },
  estimate_accepted:     { points: 50, desc: 'Deal closed' },
  proposal_created:      { points: 10, desc: 'Proposal sent' },
  job_completed:         { points: 40, desc: 'Job completed' },
  project_started:       { points: 10, desc: 'Project started' },
  review_requested:      { points: 25, desc: 'Review requested' },
  invoice_sent:          { points: 10, desc: 'Invoice sent' },
  payment_received:      { points: 20, desc: 'Payment received' },
};

async function recordScoreEvent({ company_id, entity_type, entity_id, entity_data, trigger_type }) {
  try {
    const rule = SCORE_RULES[trigger_type];
    if (!rule) return; // event not scored
    const pool = getPool();

    // Resolve which staff member to credit —
    // check common assignment fields in order of reliability
    const d = entity_data || {};
    let staffEmail = d.assigned_to || d.assigned_rep || d.sale_agent || d.assigned_staff_email || d.created_by || null;

    // For payments, pull sale_agent off the related invoice when not on the payment itself
    if (!staffEmail && entity_type === 'Payment' && d.invoice_number) {
      try {
        const invRes = await pool.query(
          `SELECT sale_agent FROM invoices WHERE invoice_number = $1 AND company_id = $2 LIMIT 1`,
          [d.invoice_number, company_id]
        );
        if (invRes.rows[0]?.sale_agent) staffEmail = invRes.rows[0].sale_agent;
      } catch { /* best-effort */ }
    }

    // For appointments / inspection jobs, look for staff_email or rep_email
    if (!staffEmail) {
      staffEmail = d.staff_email || d.rep_email || d.inspector_email || null;
    }

    // Skip if we still can't attribute the event
    if (!staffEmail || typeof staffEmail !== 'string' || !staffEmail.includes('@')) return;
    staffEmail = staffEmail.toLowerCase().trim();

    // Look up display name
    let staffName = d.assigned_rep_name || d.assigned_to_name || null;
    if (!staffName) {
      try {
        const spRes = await pool.query(
          `SELECT COALESCE(NULLIF(full_name,''), name, user_email, email) AS n FROM staff_profiles WHERE LOWER(COALESCE(NULLIF(user_email,''), email)) = $1 AND company_id = $2 LIMIT 1`,
          [staffEmail, company_id]
        );
        if (spRes.rows[0]?.n) staffName = spRes.rows[0].n;
      } catch { /* best-effort */ }
    }

    const id = require('crypto').randomUUID();
    await pool.query(
      `INSERT INTO staff_score_events (id, company_id, staff_email, staff_name, event_type, points, entity_type, entity_id, description, created_at)
       VALUES ($1, $2, $3, $4, $5, $6, $7, $8, $9, NOW())`,
      [id, company_id, staffEmail, staffName || staffEmail, trigger_type, rule.points, entity_type || null, entity_id || null, rule.desc]
    );
  } catch (err) {
    console.warn('[ScoreEngine] recordScoreEvent error:', err.message);
  }
}
