const fireOutgoingWebhooks = async (companyId, eventType, entityType, entityId, entityData) => {
  if (!companyId || !eventType) return;
  try {
    const p = getPool();
    const rows = await p.query(
      `SELECT data FROM generic_entities WHERE entity_type = 'WebhookConfig' AND company_id = $1 AND (data->>'is_active')::boolean = true`,
      [companyId]
    );
    if (rows.rows.length === 0) return;

    const matchingWebhooks = rows.rows
      .map(r => r.data)
      .filter(cfg => {
        const events = cfg.events || [];
        return events.length === 0 || events.includes(eventType) || events.includes('*');
      });

    for (const cfg of matchingWebhooks) {
      const webhookId = cfg.id;
      try {
        const payload = {
          event: eventType,
          timestamp: new Date().toISOString(),
          company_id: companyId,
          entity_type: entityType,
          entity_id: entityId,
          data: entityData || {}
        };

        const headers = { 'Content-Type': 'application/json', 'User-Agent': 'CompanySync-Webhooks/1.0' };
        if (cfg.secret) {
          const crypto = await import('crypto');
          const sig = crypto.createHmac('sha256', cfg.secret).update(JSON.stringify(payload)).digest('hex');
          headers['X-CompanySync-Signature'] = `sha256=${sig}`;
        }

        const ctrl = new AbortController();
        const timer = setTimeout(() => ctrl.abort(), 8000);
        const resp = await fetch(cfg.url, { method: 'POST', headers, body: JSON.stringify(payload), signal: ctrl.signal });
        clearTimeout(timer);

        await p.query(
          `UPDATE generic_entities SET data = data || $1, updated_date = NOW() WHERE entity_type = 'WebhookConfig' AND company_id = $2 AND data->>'id' = $3`,
          [JSON.stringify({ last_triggered: new Date().toISOString(), last_status: resp.status, failure_count: resp.ok ? 0 : (cfg.failure_count || 0) + 1 }), companyId, webhookId]
        );
        console.log(`[Webhooks] ${eventType} → ${cfg.url} → ${resp.status}`);
      } catch (err) {
        console.error(`[Webhooks] Delivery failed for ${cfg.url}:`, err.message);
        await p.query(
          `UPDATE generic_entities SET data = data || $1, updated_date = NOW() WHERE entity_type = 'WebhookConfig' AND company_id = $2 AND data->>'id' = $3`,
          [JSON.stringify({ last_triggered: new Date().toISOString(), last_status: 0, failure_count: (cfg.failure_count || 0) + 1 }), companyId, webhookId]
        ).catch(() => {});
      }
    }
  } catch (err) {
    console.error('[Webhooks] fireOutgoingWebhooks error:', err.message);
  }
};

const validateWebhookUrl = async (rawUrl) => {
  let parsed;
  try { parsed = new URL(rawUrl); } catch { return 'Invalid webhook URL format'; }
  if (parsed.protocol !== 'https:') return 'Webhook URL must use HTTPS (https://)';
  const hostname = parsed.hostname.toLowerCase();
  if (hostname === 'localhost' || hostname.endsWith('.localhost') ||
      hostname.endsWith('.local') || hostname.endsWith('.internal') ||
      hostname.endsWith('.corp') || hostname.endsWith('.lan')) {
    return 'Webhook URL must point to a public host, not an internal address';
  }
  if (_isPrivateIp(hostname)) return 'Webhook URL must not be a private/loopback IP address';
  try {
    const { address } = await dnsPromises.lookup(hostname);
    if (_isPrivateIp(address)) return 'Webhook URL resolves to a private/internal IP address';
  } catch {
    return `Webhook URL hostname "${hostname}" could not be resolved`;
  }
  return null; // valid
};

