// Centralised email sender — routes through lib/emailTransport.cjs (Postmark → SES)
const RESEND_FROM = () => process.env.EMAIL_FROM || 'CompanySync <noreply@companysync.io>';
const { PLATFORM_EMAIL_FROM, PLATFORM_EMAIL_REPLY_TO } = nodeRequire('./lib/platformEmailConfig.cjs');
const companyFrom = (name) => {
  const domain = RESEND_FROM().match(/<([^>]+)>/)?.[1] || 'noreply@companysync.io';
  return name ? `${name} <${domain}>` : RESEND_FROM();
};

function isValidEmailAddress(value) {
  return typeof value === 'string' && /^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(value.trim());
}

async function sendViaResend({ to, from, subject, html, text, attachments, cc, replyTo, context, correlationId } = {}, retries = 3) {
  return nodeRequire('./lib/emailTransport.cjs').sendPlatformEmail(
    { to, from: from || RESEND_FROM(), subject, html, text, cc, replyTo, attachments, context, correlationId },
    retries
  );
}

async function sendPlatformSubscriberEmail({ to, from, subject, html, text, attachments, cc, replyTo, context } = {}, retries = 1) {
  return nodeRequire('./lib/emailTransport.cjs').sendPlatformSubscriberEmail(
    {
      to,
      from: from || PLATFORM_EMAIL_FROM,
      replyTo: replyTo || PLATFORM_EMAIL_REPLY_TO,
      subject,
      html,
      text,
      cc,
      attachments,
      context,
    },
    retries,
  );
}

// Keep an auditable outcome for product-originated messages. Provider acceptance
// is not the same as inbox delivery, but it is the critical boundary that lets
// staff distinguish an accepted send from a rejected, failed, or skipped action.
//
// `data.delivery_status` is the canonical email outcome shown in the timeline.
// It starts at 'submitted' and is only advanced to delivered/bounced/complained
// by lib/emailDeliveryWebhook.cjs when the provider reports the terminal event.
// Returns the new communication id so a caller can link the user straight to it.
const EMAIL_SEND_STATUS_TO_DELIVERY_STATE = {
  accepted: 'submitted',
  sent: 'submitted',
  queued: 'submitted',
  failed: 'failed',
  skipped: 'skipped',
};

async function recordOutgoingEmail(pool, {
  companyId,
  to,
  contactName,
  subject,
  body,
  createdBy,
  source,
  status,
  provider,
  providerMessageId,
  error,
  entityType,
  entityId,
} = {}) {
  if (!companyId) return null;
  try {
    const recipients = Array.isArray(to) ? to : [to];
    const sendStatus = status || 'accepted';
    const communicationId = crypto.randomUUID();
    await pool.query(
      `INSERT INTO communications
        (id, company_id, type, communication_type, direction, contact_name,
         contact_email, subject, body, message, status, created_by, data,
         created_at, updated_at)
       VALUES ($1, $2, 'email', 'email', 'outbound', $3, $4, $5, $6, $6, $7, $8, $9, NOW(), NOW())`,
      [
        communicationId,
        companyId,
        contactName || null,
        recipients.filter(Boolean).join(', ') || null,
        subject || null,
        body || null,
        sendStatus,
        createdBy || 'system',
        JSON.stringify({
          source: source || 'app',
          provider: provider || null,
          provider_message_id: providerMessageId || null,
          delivery_status: EMAIL_SEND_STATUS_TO_DELIVERY_STATE[sendStatus] || sendStatus,
          delivery_status_at: new Date().toISOString(),
          delivery_detail: error || null,
          error: error || null,
          related_entity_type: entityType || null,
          related_entity_id: entityId || null,
          attempted_at: new Date().toISOString(),
        }),
      ],
    );
    return communicationId;
  } catch (error) {
    // Never turn a provider-accepted message into an apparent delivery failure
    // solely because observability storage is temporarily unavailable.
    console.warn('[Email] Could not record delivery attempt:', error.message);
    return null;
  }
}

async function recordSkippedAutomationOutreach(pool, {
  companyId,
  channel,
  to,
  contactName,
  content,
  reason,
  entityType,
  entityId,
} = {}) {
  if (!companyId) return;
  try {
    const type = channel === 'call' ? 'call' : 'sms';
    await pool.query(
      `INSERT INTO communications
        (id, company_id, type, communication_type, direction, contact_name,
         contact_phone, body, message, status, created_by, data, created_at, updated_at)
       VALUES ($1, $2, $3, $3, 'outbound', $4, $5, $6, $6, 'skipped', 'system', $7, NOW(), NOW())`,
      [
        crypto.randomUUID(),
        companyId,
        type,
        cleanAutomationContactName(contactName) || null,
        to || null,
        content || null,
        JSON.stringify({
          source: 'automation',
          error: reason || 'Missing contact name',
          related_entity_type: entityType || null,
          related_entity_id: entityId || null,
          attempted_at: new Date().toISOString(),
        }),
      ],
    );
  } catch (error) {
    console.warn('[Automation] Could not record skipped outreach:', error.message);
  }
}

// Email handlers accept internal calls (crons, workflows, webhooks) that have no
// HTTP request, so they cannot simply require `req`. But that makes a dropped
// `req` look identical to trusted internal traffic. The dispatcher marks every
// externally invoked call, so this can tell the two apart and fail closed.
function assertNotExternalWithoutRequest(params, handlerName) {
  if (params?.__externalCall) {
    console.error(`[Email] ${handlerName} was called externally without an authenticated request — refusing to send.`);
    throw new Error('Authentication required');
  }
  return null; // genuine internal caller
}

async function authorizeCompanyEmailSender(req, requestedCompanyId, channel = 'email') {
  const caller = await getUserFromRequest(req);
  if (!caller?.email) throw new Error('Authentication required');
  if (!requestedCompanyId) throw new Error('No company is selected');
  if (caller.is_super_admin) return caller;

  const pool = getPool();
  const membership = await pool.query(
    `SELECT 1
     FROM companies c
     WHERE c.id = $2
       AND (
         LOWER(COALESCE(c.created_by, '')) = LOWER($1)
         OR EXISTS (
           SELECT 1 FROM staff_profiles sp
           WHERE sp.company_id = c.id
             AND LOWER(COALESCE(NULLIF(sp.user_email, ''), sp.email)) = LOWER($1)
             AND COALESCE(sp.is_active, true) = true
         )
       )
     LIMIT 1`,
    [caller.email, requestedCompanyId],
  );
  if (!membership.rowCount) throw new Error(`You do not have access to send ${channel} for this company`);
  return caller;
}

const { isAuthenticatedManualSend } = nodeRequire('./lib/manualSendPolicy.cjs');

// Document-email authorization. The stored row's owner is authoritative: a
// client-supplied companyId must never let a caller mail another tenant's
// estimate or invoice, and a caller-built {to, subject, html} payload must be
// authorized exactly like a rendered one.
// Callers are split between camelCase (the React pages) and snake_case (server
// -side and service-role callers). Accepting only one shape means the other
// silently skips owner resolution and falls back to the caller-supplied company
// id — the wrong failure mode for the guard, so resolve both spellings.
function documentIdFrom(params, idField) {
  const snake = idField.replace(/([A-Z])/g, (m) => '_' + m.toLowerCase());
  return params?.[idField] || params?.[snake] || null;
}

async function authorizeDocumentEmail(req, params, table, idField) {
  let companyId = params?.companyId || params?.company_id || req?.headers?.['x-company-id'] || null;
  const docId = documentIdFrom(params, idField);
  if (docId) {
    // Fail CLOSED. Falling back to the caller-supplied company id on a lookup
    // error is exactly the cross-tenant hole this function exists to close: a
    // caller could send under someone else's company simply by making the
    // ownership query fail.
    let owner;
    try {
      owner = await getPool().query(`SELECT company_id FROM ${table} WHERE id = $1 LIMIT 1`, [docId]);
    } catch (e) {
      console.error(`[Email] Could not resolve ${table} owner for authorization:`, e.message);
      throw new Error('Could not verify who owns this document, so the email was not sent');
    }
    const ownerCompanyId = owner.rows[0]?.company_id;
    if (!ownerCompanyId) throw new Error('That document does not exist, so the email was not sent');
    companyId = ownerCompanyId;
  }
  const caller = await authorizeCompanyEmailSender(req, companyId);
  return { caller, companyId };
}

// ── Google Calendar disconnect: clear credentials AND tell the user ─────────
// Google revokes refresh tokens without warning — most often because the OAuth
// consent screen is still in "Testing" mode, which expires every refresh token
// after 7 days. The sync code has always DETECTED this correctly and cleared
// the stored credentials, but nothing surfaced it: sync just stopped and stayed
// broken until somebody happened to open calendar settings. (It once went
// unnoticed for 13 days while appointments piled up that never reached Google.)
//
// Every credential-clearing path funnels through here. The clearing behaviour is
// unchanged; the alert is the new part. `google_disconnect_alerted_at` is the
// idempotency gate: the sync cron runs every 15 minutes and re-enters this path
// on each tick, so only the caller that wins the NULL -> NOW() claim notifies.
// The column is reset to NULL on a successful reconnect (see the OAuth callbacks
// in this file and prod-server.cjs) so the NEXT disconnect alerts again.
// `expectedRefreshToken` is the credential whose failure triggered this call. A
// sync can take several seconds, so the user can finish reconnecting between
// Google rejecting us and this running — without the check we would wipe the
// freshly issued credentials and disconnect them again. A reconnect issues a new
// refresh token, so a mismatch means "this failure is about a connection that no
// longer exists". Pass undefined to skip the check.
async function markGoogleCalendarDisconnected(pool, targetEmail, reason, expectedRefreshToken) {
  // The credential clear and the alert claim MUST commit together under a row
  // lock. Done as two statements, a reconnect can land in between: the OAuth
  // callback resets the gate to NULL, then this claim stamps it again, and the
  // user's next real revocation finds a non-NULL gate and never alerts.
  let claimed = false;
  let companyId = null;
  let claimStamp = null;
  const client = await pool.connect();
  try {
    await client.query('BEGIN');
    const cur = await client.query(
      `SELECT company_id, google_disconnect_alerted_at, google_refresh_token
       FROM users WHERE email = $1 FOR UPDATE`,
      [targetEmail]
    );
    if (!cur.rowCount) {
      await client.query('ROLLBACK');
      return { cleared: false, alerted: false };
    }
    if (expectedRefreshToken !== undefined
        && cur.rows[0].google_refresh_token !== expectedRefreshToken) {
      await client.query('ROLLBACK');
      console.log('[Calendar] Credentials changed since the failure for', targetEmail, '- not clearing (likely reconnected mid-sync)');
      return { cleared: false, alerted: false, stale: true };
    }
    claimed = cur.rows[0].google_disconnect_alerted_at === null;
    companyId = cur.rows[0].company_id || null;
    const upd = await client.query(
      `UPDATE users SET google_calendar_connected = false, google_access_token = NULL,
       google_refresh_token = NULL, google_token_expires_at = NULL,
       google_sync_enabled = false, google_calendar_reconnect_needed = true,
       google_disconnect_alerted_at = COALESCE(google_disconnect_alerted_at, NOW()),
       updated_at = NOW() WHERE email = $1
       RETURNING google_disconnect_alerted_at`,
      [targetEmail]
    );
    claimStamp = upd.rows[0]?.google_disconnect_alerted_at || null;
    await client.query('COMMIT');
  } catch (e) {
    try { await client.query('ROLLBACK'); } catch (_) {}
    console.error('[Calendar] Failed to clear revoked Google credentials:', e.message);
    return { cleared: false, alerted: false };
  } finally {
    client.release();
  }

  if (!claimed) {
    console.log('[Calendar] Disconnect alert already sent for', targetEmail, '- not re-sending');
    return { cleared: true, alerted: false };
  }

  console.log(`[Calendar] Google Calendar disconnected for ${targetEmail} (${reason}) - sending alert`);

  // users.company_id is frequently NULL; fall back the same way the sync does.
  if (!companyId) {
    try {
      const staff = await pool.query('SELECT company_id FROM staff_profiles WHERE user_email = $1 LIMIT 1', [targetEmail]);
      companyId = staff.rows[0]?.company_id || null;
      if (!companyId) {
        const owned = await pool.query('SELECT id FROM companies WHERE created_by = $1 LIMIT 1', [targetEmail]);
        companyId = owned.rows[0]?.id || null;
      }
    } catch (e) {
      console.warn('[Calendar] Could not resolve company for disconnect alert:', e.message);
    }
  }

  // How many CRM events are already sitting unsynced? This is the number that
  // makes the alert actionable — "reconnect" is abstract, "8 appointments are
  // not on your Google Calendar" is not.
  let pendingCount = 0;
  try {
    const pending = await pool.query(
      `SELECT COUNT(*)::int AS n FROM calendar_events
       WHERE assigned_to = $1 AND google_event_id IS NULL
         AND start_time >= NOW() - INTERVAL '30 days'`,
      [targetEmail]
    );
    pendingCount = pending.rows[0]?.n || 0;
  } catch (e) {
    console.warn('[Calendar] Could not count unsynced events for alert:', e.message);
  }

  const calendarUrl = `${getAppUrl()}/Calendar`;
  const pendingLine = pendingCount > 0
    ? `<p style="margin:0 0 16px;font-size:15px;color:#b91c1c;"><strong>${pendingCount} appointment${pendingCount === 1 ? '' : 's'}</strong> created since then ${pendingCount === 1 ? 'is' : 'are'} not on your Google Calendar. Reconnecting will push ${pendingCount === 1 ? 'it' : 'them'} across automatically.</p>`
    : '';

  // Track delivery so a total failure can hand the claim back. Winning the
  // claim reserves the right to alert; it must not be mistaken for having
  // actually alerted, or one transient mail outage silences this disconnect
  // forever (the same trap the trial-nurture sender fell into).
  let delivered = false;

  try {
    await sendViaResend({
      to: targetEmail,
      subject: 'Action needed: your Google Calendar stopped syncing',
      html: `<div style="font-family:-apple-system,BlinkMacSystemFont,'Segoe UI',Roboto,sans-serif;max-width:560px;margin:0 auto;padding:24px;">
        <h2 style="color:#b91c1c;margin:0 0 12px;">Google Calendar disconnected</h2>
        <p style="margin:0 0 16px;font-size:15px;color:#374151;">Google ended the connection between CompanySync and your Google Calendar, so new appointments have stopped syncing across.</p>
        ${pendingLine}
        <p style="margin:0 0 20px;font-size:15px;color:#374151;">Click below and choose your Google account to restore syncing. It takes about ten seconds.</p>
        <p style="margin:0 0 24px;"><a href="${calendarUrl}" style="display:inline-block;background:#2563eb;color:#fff;padding:12px 28px;border-radius:8px;text-decoration:none;font-weight:600;">Reconnect Google Calendar</a></p>
        <p style="margin:0;font-size:13px;color:#6b7280;border-top:1px solid #e5e7eb;padding-top:16px;">If this keeps happening every week, your Google Cloud OAuth consent screen is still set to "Testing", which expires the connection every 7 days. Publishing it to "In production" stops the repeat disconnects.</p>
      </div>`,
    });
    delivered = true;
  } catch (e) {
    console.error('[Calendar] Disconnect alert email failed:', e.message);
  }

  // Bell notification. Notifications live in generic_entities under
  // entity_type 'Notification' (there is no `notifications` table — raw
  // INSERTs against one silently do nothing), and generic_entities.id has no
  // DB default, so the id must be supplied explicitly.
  if (companyId) {
    try {
      await pool.query(
        `INSERT INTO generic_entities (id, entity_type, company_id, data, created_date, updated_date)
         VALUES ($1, 'Notification', $2, $3::jsonb, NOW(), NOW())
         ON CONFLICT (id, entity_type) DO NOTHING`,
        [
          generateEntityId('notif'),
          companyId,
          JSON.stringify({
            user_email: targetEmail,
            title: '⚠️ Google Calendar disconnected',
            message: pendingCount > 0
              ? `Sync has stopped and ${pendingCount} appointment${pendingCount === 1 ? '' : 's'} did not reach Google. Reconnect to restore it.`
              : 'Sync has stopped. Reconnect your Google Calendar to restore it.',
            type: 'calendar_disconnected',
            link_url: '/Calendar',
            is_read: false,
          }),
        ]
      );
      delivered = true;
    } catch (e) {
      console.error('[Calendar] Disconnect bell notification failed:', e.message);
    }
  }

  // Nothing reached the user on any channel — hand the claim back so the next
  // sync tick retries. Only when BOTH channels failed, so a partial success
  // never turns into duplicate alerts.
  if (!delivered) {
    console.error('[Calendar] No disconnect alert channel succeeded for', targetEmail, '- releasing claim for retry');
    try {
      // Scoped to the exact stamp we claimed: if the user reconnected and hit a
      // fresh disconnect while we were failing to send, that newer claim is a
      // different timestamp and must not be cleared by this stale release.
      await pool.query(
        `UPDATE users SET google_disconnect_alerted_at = NULL
         WHERE email = $1 AND google_calendar_reconnect_needed = true
           AND google_disconnect_alerted_at = $2`,
        [targetEmail, claimStamp]
      );
    } catch (e) {
      console.error('[Calendar] Failed to release disconnect alert claim:', e.message);
    }
    return { cleared: true, alerted: false };
  }

  return { cleared: true, alerted: true, pendingCount };
}

// Google access tokens last about an hour, while the refresh token is the
// durable connection. Refreshes must be serialized separately from the larger
// calendar sync lock: the refresh currently happens before that lock is
// acquired, and overlapping browser/cron syncs can otherwise submit the same
// refresh token twice. Google may rotate refresh tokens, so the replacement
// must be persisted before releasing the lock.
async function getGoogleCalendarAccessToken(pool, targetEmail, {
  clientId,
  clientSecret,
  forceRefresh = false,
} = {}) {
  const lockKey = 'gcal_token_refresh:' + targetEmail;
  const client = await pool.connect();
  let locked = false;
  try {
    await client.query('SELECT pg_advisory_lock(hashtext($1))', [lockKey]);
    locked = true;

    const result = await client.query(
      `SELECT google_access_token, google_refresh_token, google_token_expires_at,
              last_google_sync
       FROM users WHERE email = $1`,
      [targetEmail]
    );
    const row = result.rows[0];
    if (!row?.google_access_token) {
      return { accessToken: null, user: row || null };
    }

    const expiresAt = row.google_token_expires_at ? new Date(row.google_token_expires_at).getTime() : 0;
    const refreshNeeded = forceRefresh || !expiresAt || expiresAt <= Date.now() + 5 * 60 * 1000;
    if (!refreshNeeded) {
      return { accessToken: row.google_access_token, user: row, refreshed: false };
    }
    if (!row.google_refresh_token || !clientId || !clientSecret) {
      return {
        accessToken: null,
        user: row,
        error: !row.google_refresh_token
          ? 'Google refresh token is missing.'
          : 'Google OAuth client is not configured.',
        revoked: false,
      };
    }

    const tokenResp = await fetch('https://oauth2.googleapis.com/token', {
      method: 'POST',
      headers: { 'Content-Type': 'application/x-www-form-urlencoded' },
      body: new URLSearchParams({
        client_id: clientId,
        client_secret: clientSecret,
        refresh_token: row.google_refresh_token,
        grant_type: 'refresh_token',
      }),
    });
    const tokens = await tokenResp.json();
    if (!tokenResp.ok || !tokens.access_token) {
      const revoked = tokens.error === 'invalid_grant';
      console.error('[Calendar] Refresh failed:', JSON.stringify({
        error: tokens.error,
        error_description: tokens.error_description,
        status: tokenResp.status,
      }));
      return {
        accessToken: null,
        user: row,
        error: tokens.error_description || tokens.error || `Google token refresh failed (${tokenResp.status})`,
        revoked,
        expectedRefreshToken: row.google_refresh_token,
      };
    }

    const nextRefreshToken = tokens.refresh_token || row.google_refresh_token;
    const nextExpiresAt = new Date(Date.now() + (Number(tokens.expires_in) || 3600) * 1000).toISOString();
    await client.query(
      `UPDATE users
       SET google_access_token = $1,
           google_refresh_token = $2,
           google_token_expires_at = $3,
           updated_at = NOW()
       WHERE email = $4 AND google_refresh_token = $5`,
      [tokens.access_token, nextRefreshToken, nextExpiresAt, targetEmail, row.google_refresh_token]
    );
    return {
      accessToken: tokens.access_token,
      user: { ...row, google_access_token: tokens.access_token, google_refresh_token: nextRefreshToken, google_token_expires_at: nextExpiresAt },
      refreshed: true,
    };
  } catch (error) {
    console.error('[Calendar] Token refresh error:', error.message);
    return { accessToken: null, error: 'Failed to connect to Google for refresh.', revoked: false };
  } finally {
    try {
      if (locked) await client.query('SELECT pg_advisory_unlock(hashtext($1))', [lockKey]);
    } catch (unlockError) {
      console.error('[Calendar] Failed to release token refresh lock:', unlockError.message);
    }
    client.release();
  }
}

async function markMicrosoftCalendarDisconnected(pool, targetEmail, reason, {
  expectedAccessToken,
  expectedRefreshToken,
} = {}) {
  let claimed = false;
  let companyId = null;
  let claimStamp = null;
  const client = await pool.connect();
  try {
    await client.query('BEGIN');
    const cur = await client.query(
      `SELECT company_id, microsoft_disconnect_alerted_at,
              microsoft_access_token, microsoft_refresh_token
       FROM users WHERE email = $1 FOR UPDATE`,
      [targetEmail]
    );
    if (!cur.rowCount) {
      await client.query('ROLLBACK');
      return { cleared: false, alerted: false };
    }
    if ((expectedAccessToken !== undefined && cur.rows[0].microsoft_access_token !== expectedAccessToken)
        || (expectedRefreshToken !== undefined && cur.rows[0].microsoft_refresh_token !== expectedRefreshToken)) {
      await client.query('ROLLBACK');
      console.log('[MSCalendar] Credentials changed since the failure for', targetEmail, '- not clearing (likely reconnected mid-sync)');
      return { cleared: false, alerted: false, stale: true };
    }
    claimed = cur.rows[0].microsoft_disconnect_alerted_at === null;
    companyId = cur.rows[0].company_id || null;
    const upd = await client.query(
      `UPDATE users SET microsoft_calendar_connected = false,
       microsoft_access_token = NULL, microsoft_refresh_token = NULL,
       microsoft_token_expires_at = NULL, microsoft_sync_enabled = false,
       microsoft_disconnect_alerted_at = COALESCE(microsoft_disconnect_alerted_at, NOW()),
       updated_at = NOW() WHERE email = $1
       RETURNING microsoft_disconnect_alerted_at`,
      [targetEmail]
    );
    claimStamp = upd.rows[0]?.microsoft_disconnect_alerted_at || null;
    await client.query('COMMIT');
  } catch (e) {
    try { await client.query('ROLLBACK'); } catch (_) {}
    console.error('[MSCalendar] Failed to clear revoked Microsoft credentials:', e.message);
    return { cleared: false, alerted: false };
  } finally {
    client.release();
  }

  if (!claimed) {
    console.log('[MSCalendar] Disconnect alert already sent for', targetEmail, '- not re-sending');
    return { cleared: true, alerted: false };
  }

  if (!companyId) {
    try {
      const staff = await pool.query(
        'SELECT company_id FROM staff_profiles WHERE (user_email = $1 OR email = $1) LIMIT 1',
        [targetEmail]
      );
      companyId = staff.rows[0]?.company_id || null;
      if (!companyId) {
        const owned = await pool.query('SELECT id FROM companies WHERE created_by = $1 LIMIT 1', [targetEmail]);
        companyId = owned.rows[0]?.id || null;
      }
    } catch (e) {
      console.warn('[MSCalendar] Could not resolve company for disconnect alert:', e.message);
    }
  }

  let pendingCount = 0;
  try {
    const pending = await pool.query(
      `SELECT COUNT(*)::int AS n FROM calendar_events
       WHERE (assigned_to = $1 OR created_by = $1) AND outlook_event_id IS NULL
         AND start_time >= NOW() - INTERVAL '30 days'`,
      [targetEmail]
    );
    pendingCount = pending.rows[0]?.n || 0;
  } catch (e) {
    console.warn('[MSCalendar] Could not count unsynced events for alert:', e.message);
  }

  const calendarUrl = `${getAppUrl()}/Calendar`;
  const pendingText = pendingCount > 0
    ? `${pendingCount} appointment${pendingCount === 1 ? '' : 's'} ${pendingCount === 1 ? 'has' : 'have'} not reached Outlook. `
    : '';
  let delivered = false;
  try {
    await sendViaResend({
      to: targetEmail,
      subject: 'Action needed: your Outlook Calendar stopped syncing',
      html: `<div style="font-family:-apple-system,BlinkMacSystemFont,'Segoe UI',Roboto,sans-serif;max-width:560px;margin:0 auto;padding:24px;">
        <h2 style="color:#b91c1c;margin:0 0 12px;">Outlook Calendar disconnected</h2>
        <p style="margin:0 0 16px;font-size:15px;color:#374151;">Microsoft ended the connection between CompanySync and your Outlook Calendar, so appointments have stopped syncing.</p>
        ${pendingCount > 0 ? `<p style="margin:0 0 16px;font-size:15px;color:#b91c1c;"><strong>${pendingCount} appointment${pendingCount === 1 ? '' : 's'}</strong> ${pendingCount === 1 ? 'has' : 'have'} not reached Outlook. Reconnecting will push ${pendingCount === 1 ? 'it' : 'them'} across automatically.</p>` : ''}
        <p style="margin:0 0 24px;"><a href="${calendarUrl}" style="display:inline-block;background:#0078d4;color:#fff;padding:12px 28px;border-radius:8px;text-decoration:none;font-weight:600;">Reconnect Outlook Calendar</a></p>
      </div>`,
    });
    delivered = true;
  } catch (e) {
    console.error('[MSCalendar] Disconnect alert email failed:', e.message);
  }

  if (companyId) {
    try {
      await pool.query(
        `INSERT INTO generic_entities (id, entity_type, company_id, data, created_date, updated_date)
         VALUES ($1, 'Notification', $2, $3::jsonb, NOW(), NOW())
         ON CONFLICT (id, entity_type) DO NOTHING`,
        [
          generateEntityId('notif'),
          companyId,
          JSON.stringify({
            user_email: targetEmail,
            title: '⚠️ Outlook Calendar disconnected',
            message: `${pendingText}Reconnect your Outlook Calendar to restore syncing.`,
            type: 'microsoft_calendar_disconnected',
            link_url: '/Calendar',
            is_read: false,
          }),
        ]
      );
      delivered = true;
    } catch (e) {
      console.error('[MSCalendar] Disconnect bell notification failed:', e.message);
    }
  }

  if (!delivered) {
    try {
      await pool.query(
        `UPDATE users SET microsoft_disconnect_alerted_at = NULL
         WHERE email = $1 AND microsoft_calendar_connected = false
           AND microsoft_disconnect_alerted_at = $2`,
        [targetEmail, claimStamp]
      );
    } catch (e) {
      console.error('[MSCalendar] Failed to release disconnect alert claim:', e.message);
    }
    return { cleared: true, alerted: false };
  }
  console.log(`[MSCalendar] Outlook Calendar disconnected for ${targetEmail} (${reason}) - alert delivered`);
  return { cleared: true, alerted: true, pendingCount };
}

async function logIntegrationActivity(service, action, status, details = {}) {
  try {
    const p = getPool();
    const id = `intlog_${Date.now()}_${Math.random().toString(36).substr(2, 6)}`;
    const logData = { service, action, status, timestamp: new Date().toISOString(), duration_ms: details.duration_ms || null, error_message: details.error || null, details: details.meta || null };
    await p.query(`INSERT INTO generic_entities (id, entity_type, company_id, data, created_date, updated_date) VALUES ($1, 'IntegrationLog', 'companysync_master_001', $2, NOW(), NOW())`, [id, JSON.stringify(logData)]);
  } catch (e) { /* silently fail logging */ }
}

const USAGE_UNIT_COSTS = {
  lexi: 0.05,
  sarah: 0.10,
  sms_ai: 0.02,
  ai_estimator: 0.08,
  marcus: 0.06,
  crew_cam: 0.12,
  ai: 0.04,       // Gemini image generation (color visualizer) — ~$0.04/image on our key
  ai_byok: 0,     // generation ran on the company's OWN Gemini key → free to us (visibility only)
};

async function callLexiBridge(action, companyId, data = null) {
  const url = process.env.BASE44_LEXI_BRIDGE_API_URL;
  const secret = process.env.LEXI_NATIVE_BRIDGE_SECRET;
  if (!url || !secret) return null;
  try {
    const body = { action, companyId };
    if (data) body.data = data;
    const resp = await fetch(url, {
      method: 'POST',
      headers: { 'Content-Type': 'application/json', 'Authorization': `Bearer ${secret}` },
      body: JSON.stringify(body),
    });
    if (!resp.ok) return { error: `HTTP ${resp.status}` };
    const text = await resp.text();
    try {
      const parsed = JSON.parse(text);
      return parsed;
    } catch {
      return { error: `Non-JSON response from bridge (status ${resp.status})` };
    }
  } catch (err) {
    console.warn('[LexiBridge] callLexiBridge error:', err.message);
    return { error: err.message };
  }
}

async function logUsageEvent(companyId, feature, units = 1) {
  if (!companyId || companyId === 'companysync_master_001') return;
  try {
    const p = getPool();
    // `??` not `||` — an explicit 0 cost (ai_byok) must stay 0, not fall back to 0.05.
    const unitCost = USAGE_UNIT_COSTS[feature] ?? 0.05;
    const totalCost = unitCost * units;
    const now = new Date();
    const usageMonth = now.toISOString().slice(0, 7);
    const usageDate  = now.toISOString().slice(0, 10);
    const id = `usage_${Date.now()}_${Math.random().toString(36).substr(2, 9)}`;
    const data = { company_id: companyId, feature, units, unit_cost: unitCost, total_cost: totalCost, usage_month: usageMonth, usage_date: usageDate, logged_at: now.toISOString() };
    await p.query(
      `INSERT INTO generic_entities (id, entity_type, company_id, data, created_date, updated_date) VALUES ($1, 'SubscriptionUsage', $2, $3, NOW(), NOW())`,
      [id, companyId, JSON.stringify(data)]
    );
  } catch (e) {
    console.error('[Usage] Failed to log usage event:', e.message);
  }
}

// Feature keys that count toward a company's monthly "AI interaction" limit.
// MUST stay in sync with the ai_used filter in src/pages/SubscriptionUsage.jsx.
const AI_USAGE_FEATURES = ['lexi', 'ai', 'ai_estimator', 'crew_cam', 'marcus', 'check_payment'];

// Mirrors the PLAN_LIMITS map in src/pages/SubscriptionUsage.jsx (-1 = unlimited).
const AI_PLAN_LIMITS = {
  trial: 50,
  basic: 1000,
  business: 5000,
  // Enterprise on platform key: capped at 50,000/month to prevent runaway cost.
  // BYOK (own Gemini key) companies always bypass this cap entirely — see
  // getCompanyGeminiKeyInfo early-return above.
  enterprise: 50000,
  legacy: 50000,
  lifetime: 50000,
  unlimited: 50000,
  professional: 10000,
};

// Daily limits for trial companies — refresh at UTC midnight every day.
// Sized so a user can meaningfully test each day's drip-campaign feature
// without exhausting their entire trial budget on one session.
const TRIAL_DAILY_LIMITS = {
  ai:    15,   // AI calls (all AI_USAGE_FEATURES combined)
  sms:   20,   // outbound SMS sent via the company's Twilio / platform number
  email: 30,   // outbound emails sent via sendEmail/sendEmailWithBranding/sendEmailWithResend
};

// Dollar-based platform-spend circuit breaker (mirrors banner thresholds in
// src/pages/SubscriptionUsage.jsx). Interaction counts alone don't bound cost —
// features range $0.02–$0.12/unit — so a heavy company could hit $6,000/mo
// before the 50k count cap. These caps bound worst-case platform spend per
// company so a $299 subscription stays profitable. BYOK companies bypass
// entirely (their usage is logged at $0 and they early-return before this).
const AI_SPEND_WARN_USD = 150;      // once-per-month warning email + banner
const AI_SPEND_HARD_CAP_USD = 200;  // platform-key AI features blocked

function shouldSuppressUsageAlertEmails(companyId, company = {}) {
  return company.is_deleted === true || /^smoke[_-]/i.test(String(companyId || ''));
}

// Short-lived per-company result cache for checkAIUsage.
// Stores the last successful { allowed, ... } result for up to 5 minutes.
// On DB errors, we fall back to the cached result instead of failing open —
// so a transient outage can't let an over-limit subscriber slip through,
// and a legitimate subscriber isn't suddenly hard-blocked mid-session.
const _aiUsageCache = new Map(); // companyId -> { result, ts }
const AI_USAGE_CACHE_TTL_MS = 5 * 60 * 1000; // 5 minutes

// Gate for every paid-model AI feature (Gemini/GPT-4o vision & extraction calls).
// Policy: BYOK Gemini key → no cap (platform pays nothing).
//         Platform key, paid plan → hard monthly cap enforced.
//         Trial → existing daily cap.
// Falls back to last-known cached result on DB errors (not blindly open).
async function checkAIUsage(companyId, options = {}) {
  // Smoke tests exercise the same cap/notice-idempotency logic as production,
  // but must never email real platform administrators.
  const explicitlySuppressEmailNotifications = options.suppressEmailNotifications === true;
  if (!companyId || companyId === 'companysync_master_001') return { allowed: true };
  try {
    const p = getPool();
    const companyRes = await p.query(
      'SELECT subscription_plan, ai_credits_purchased, company_name, is_deleted FROM companies WHERE id = $1',
      [companyId]
    );
    const company = companyRes.rows[0];
    if (!company || company.company_name === 'CompanySync') return { allowed: true };
    const suppressEmailNotifications = explicitlySuppressEmailNotifications
      || shouldSuppressUsageAlertEmails(companyId, company);

    const plan = company.subscription_plan || 'trial';

    // Trial companies: daily refresh (15/day) instead of the flat monthly limit.
    // Trials always go through the cap regardless of any key configuration.
    if (plan === 'trial') {
      const usageDate = new Date().toISOString().slice(0, 10);
      const dailyRes = await p.query(
        `SELECT COALESCE(SUM((data->>'units')::numeric), 0) AS used
         FROM generic_entities
         WHERE entity_type = 'SubscriptionUsage' AND company_id = $1
           AND data->>'usage_date' = $2 AND data->>'feature' = ANY($3::text[])`,
        [companyId, usageDate, AI_USAGE_FEATURES]
      );
      const dailyUsed = Number(dailyRes.rows[0]?.used || 0);
      if (dailyUsed >= TRIAL_DAILY_LIMITS.ai) {
        const result = { allowed: false, error: `Daily AI limit reached for your free trial (${TRIAL_DAILY_LIMITS.ai} per day). Your limit refreshes tomorrow — or upgrade to unlock more.` };
        _aiUsageCache.set(companyId, { result, ts: Date.now() });
        return result;
      }
      const result = { allowed: true };
      _aiUsageCache.set(companyId, { result, ts: Date.now() });
      return result;
    }

    // Paid plan: BYOK check — if the company has their own Gemini key configured,
    // those calls cost the platform nothing, so there is no cap to enforce.
    const { isOwn: hasByokGemini } = await getCompanyGeminiKeyInfo(companyId);
    if (hasByokGemini) {
      const result = { allowed: true, byok: true };
      _aiUsageCache.set(companyId, { result, ts: Date.now() });
      return result;
    }

    // Paid plan on platform key: enforce the monthly interaction cap.
    const planLimit = AI_PLAN_LIMITS[plan] ?? AI_PLAN_LIMITS.trial;
    const limit = planLimit === -1 ? -1 : planLimit + (company.ai_credits_purchased || 0);
    if (limit === -1) {
      const result = { allowed: true };
      _aiUsageCache.set(companyId, { result, ts: Date.now() });
      return result;
    }

    const usageMonth = new Date().toISOString().slice(0, 7);
    // One query, two aggregates over the SAME feature set this gate blocks
    // (AI_USAGE_FEATURES): interaction count for the count cap, and
    // month-to-date platform $ spend for the spend circuit breaker.
    // SMS/voice spend is deliberately excluded — those have their own caps,
    // and blocking AI over SMS usage would be wrong (BYOK Gemini wouldn't fix
    // it). BYOK AI events are logged as 'ai_byok' at $0, outside this set.
    const usageRes = await p.query(
      `SELECT COALESCE(SUM((data->>'units')::numeric), 0) AS used,
              COALESCE(SUM((data->>'total_cost')::numeric), 0) AS mtd_spend
       FROM generic_entities
       WHERE entity_type = 'SubscriptionUsage' AND company_id = $1
         AND data->>'usage_month' = $2 AND data->>'feature' = ANY($3::text[])`,
      [companyId, usageMonth, AI_USAGE_FEATURES]
    );
    const used = Number(usageRes.rows[0]?.used || 0);
    const mtdSpend = Number(usageRes.rows[0]?.mtd_spend || 0);

    // Hard stop: month-to-date platform spend crossed the dollar cap.
    if (mtdSpend >= AI_SPEND_HARD_CAP_USD) {
      notifySpendHardStop(companyId, usageMonth, mtdSpend, { sendEmails: !suppressEmailNotifications }).catch((e) =>
        console.error('[Usage] notifySpendHardStop failed:', e.message));
      const result = { allowed: false, mtdSpend, error: `Monthly AI usage limit reached for your plan this month. Add your own Gemini API key in Settings → API Keys to remove this limit instantly, or wait until next month.` };
      _aiUsageCache.set(companyId, { result, ts: Date.now() });
      return result;
    }
    // Warning threshold: fire the once-per-month heavy-user email (idempotent).
    if (mtdSpend >= AI_SPEND_WARN_USD) {
      sendSpendWarning(companyId, usageMonth, mtdSpend, { sendEmail: !suppressEmailNotifications }).catch((e) =>
        console.error('[Usage] sendSpendWarning failed:', e.message));
    }

    // 80% nudge: fire once per month when the subscriber first crosses 80% of their cap.
    // Checked BEFORE the hard-cap block so a jump from <80% directly to ≥100% in one
    // request still creates the nudge. BYOK companies and trials early-return above, so
    // we only reach here for platform-key paid subscribers — the exact audience we want.
    if (used >= Math.ceil(limit * 0.8)) {
      sendAIUsageNudge(companyId, usageMonth, used, limit, { sendEmail: !suppressEmailNotifications }).catch((e) =>
        console.warn('[Usage] sendAIUsageNudge async failed:', e.message));
    }
    if (used >= limit) {
      const result = { allowed: false, error: `Monthly AI limit reached (${used.toLocaleString()}/${limit.toLocaleString()} interactions). Add your own Gemini API key in Settings → API Keys to remove this limit instantly, or upgrade your plan.` };
      _aiUsageCache.set(companyId, { result, ts: Date.now() });
      return result;
    }
    const result = { allowed: true, mtdSpend };
    _aiUsageCache.set(companyId, { result, ts: Date.now() });
    return result;
  } catch (e) {
    // DB error: use the last cached result if it's still fresh (5 min TTL).
    // This prevents a transient DB hiccup from acting as an "always allow" bypass.
    const cached = _aiUsageCache.get(companyId);
    if (cached && Date.now() - cached.ts < AI_USAGE_CACHE_TTL_MS) {
      console.warn('[Usage] checkAIUsage DB error — using cached result:', e.message);
      return cached.result;
    }
    // Cache stale or absent: fail open, but log loudly.
    console.error('[Usage] checkAIUsage error (failing open — no fresh cache):', e.message);
    return { allowed: true };
  }
}

// Stamp a once-per-month UsageNudge record so the 80% warning fires at most once
// per cap per billing month.  The id is deterministic so concurrent calls can't
// double-fire: ON CONFLICT DO NOTHING + rowCount tells us whether WE won the race.
async function claimUsageNudge(p, companyId, usageMonth, capType) {
  const id = `usagenudge_${companyId}_${usageMonth}_${capType}`;
  const res = await p.query(
    `INSERT INTO generic_entities (id, entity_type, company_id, data, created_date, updated_date)
     VALUES ($1, 'SubscriptionUsageNudge', $2, $3, NOW(), NOW())
     ON CONFLICT (id, entity_type) DO NOTHING`,
    [id, companyId, JSON.stringify({ company_id: companyId, nudge_month: usageMonth, cap_type: capType, sent_at: new Date().toISOString() })]
  );
  return res.rowCount > 0;
}

// Send a once-per-month 80%-cap warning for AI interactions.
// Creates in-app Notification entities for every admin user, plus a brief
// email to the company owner (created_by).
async function sendAIUsageNudge(companyId, usageMonth, used, limit, { sendEmail = true } = {}) {
  const p = getPool();
  if (!(await claimUsageNudge(p, companyId, usageMonth, 'ai_interactions'))) return;

  const { rows } = await p.query(
    `SELECT COALESCE(company_name, data->>'company_name', id) AS name, created_by, is_deleted
     FROM companies WHERE id = $1`,
    [companyId]
  );
  const company = rows[0];
  if (!company) return;
  sendEmail = sendEmail && !shouldSuppressUsageAlertEmails(companyId, company);

  const title = `You've used ${used.toLocaleString()} of ${limit.toLocaleString()} AI interactions this month`;
  const message = `You're approaching your monthly AI interaction limit. Add your own Gemini API key in Settings → API Keys to remove this limit entirely — it takes about 2 minutes.`;
  const linkUrl = '/APIKeysSettings';
  const appUrl = getAppUrl();
  const now = new Date().toISOString();

  // In-app bell for every admin user at this company.
  try {
    const { rows: adminRows } = await p.query(
      `SELECT COALESCE(NULLIF(user_email,''), email) AS email
       FROM staff_profiles
       WHERE company_id = $1 AND is_administrator = true AND is_active = true
         AND COALESCE(NULLIF(user_email,''), email) IS NOT NULL`,
      [companyId]
    );
    for (const { email } of adminRows) {
      await p.query(
        `INSERT INTO generic_entities (id, entity_type, company_id, data, created_date, updated_date)
         VALUES ($1, 'Notification', $2, $3, NOW(), NOW())`,
        [generateEntityId('notif'), companyId, JSON.stringify({
          company_id: companyId, user_email: email, title, message,
          type: 'usage_nudge', link_url: linkUrl, is_read: false, created_at: now,
        })]
      );
    }
  } catch (e) {
    console.warn(`[Usage] AI nudge bell creation failed for ${companyId}:`, e.message);
  }

  // Email to company owner (created_by). Smoke tests retain the in-app record
  // coverage but suppress all real outbound messages.
  if (sendEmail && company.created_by) {
    try {
      await functionHandlers.sendEmailWithResend({
        to: company.created_by,
        companyId,
        subject: title,
        html: `<div style="font-family:sans-serif;max-width:600px;margin:0 auto;padding:20px;">
          <h2 style="color:#1f2937;margin-top:0;">You're approaching your AI interaction limit</h2>
          <p style="color:#374151;">Your company has used <strong>${used.toLocaleString()} of ${limit.toLocaleString()} AI interactions</strong> this month (80% of your monthly cap).</p>
          <div style="background:#fffbeb;border:1px solid #fde68a;border-radius:8px;padding:16px;margin:16px 0;">
            <p style="color:#92400e;margin:0;"><strong>Heads-up:</strong> once you hit ${limit.toLocaleString()} interactions, AI features will be paused for the rest of the month. Add your own Gemini API key to remove this limit entirely — it takes about 2 minutes.</p>
          </div>
          <p style="margin-top:24px;">
            <a href="${appUrl}/APIKeysSettings" style="background:#2563eb;color:white;padding:10px 20px;text-decoration:none;border-radius:6px;display:inline-block;font-size:14px;">Add your own API key →</a>
          </p>
        </div>`,
      });
    } catch (emailErr) {
      console.warn(`[Usage] AI nudge email to ${company.created_by} failed:`, emailErr.message);
      // Don't un-claim — the in-app bells already fired.
    }
  }
  console.log(`[Usage] AI interaction nudge sent for ${company.name} — ${used.toLocaleString()}/${limit.toLocaleString()} (${usageMonth})`);
}

// Stamp a once-per-month SpendNotice record. The id is deterministic
// (company + month + kind) so concurrent checkAIUsage calls can't double-send:
// ON CONFLICT DO NOTHING + rowCount tells us whether WE won the race.
async function claimSpendNotice(companyId, usageMonth, kind, mtdSpend) {
  const p = getPool();
  const id = `spendnotice_${companyId}_${usageMonth}_${kind}`;
  const res = await p.query(
    `INSERT INTO generic_entities (id, entity_type, company_id, data, created_date, updated_date)
     VALUES ($1, 'SpendNotice', $2, $3, NOW(), NOW())
     ON CONFLICT (id, entity_type) DO NOTHING`,
    [id, companyId, JSON.stringify({ company_id: companyId, notice_month: usageMonth, kind, mtd_spend: mtdSpend, sent_at: new Date().toISOString() })]
  );
  return res.rowCount > 0;
}

// $150 crossed: one warning email per month to the company owner with the
// BYOK pitch. The in-app banner is computed client-side on SubscriptionUsage.
async function sendSpendWarning(companyId, usageMonth, mtdSpend, { sendEmail = true } = {}) {
  if (!(await claimSpendNotice(companyId, usageMonth, 'warning', mtdSpend))) return;
  const p = getPool();
  const { rows } = await p.query(
    `SELECT COALESCE(company_name, data->>'company_name', id) AS name, created_by, is_deleted
     FROM companies WHERE id = $1`, [companyId]);
  const company = rows[0];
  if (!company?.created_by) return;
  sendEmail = sendEmail && !shouldSuppressUsageAlertEmails(companyId, company);
  if (!sendEmail) {
    console.log(`[Usage] Spend warning recorded without email for ${company.name} (test mode)`);
    return;
  }
  const appUrl = getAppUrl();
  try {
  await functionHandlers.sendEmailWithResend({
    to: company.created_by,
    companyId,
    subject: `You're one of our heaviest AI users this month — here's how to keep it unlimited`,
    html: `<div style="font-family:sans-serif;max-width:600px;margin:0 auto;padding:20px;">
      <h2 style="color:#1f2937;margin-top:0;">Your team is getting serious value from AI 🎉</h2>
      <p style="color:#374151;">Your company has used <strong>$${mtdSpend.toFixed(2)}</strong> of AI processing this month — that puts you among our heaviest users.</p>
      <p style="color:#374151;">To keep costs sustainable, accounts approaching <strong>$${AI_SPEND_HARD_CAP_USD}</strong>/month in AI usage on our shared keys are paused until the next month. You're getting close.</p>
      <div style="background:#eff6ff;border:1px solid #bfdbfe;border-radius:8px;padding:16px;margin:16px 0;">
        <p style="color:#1e40af;margin:0;"><strong>The good news:</strong> connect your own Google Gemini API key and AI becomes truly unlimited — no caps, no pauses, ever. It takes about 2 minutes.</p>
      </div>
      <p style="margin-top:24px;">
        <a href="${appUrl}/APIKeysSettings" style="background:#2563eb;color:white;padding:10px 20px;text-decoration:none;border-radius:6px;display:inline-block;font-size:14px;">Add your own API key →</a>
      </p>
    </div>`,
  });
  } catch (emailErr) {
    // Release the claim so a transient email outage doesn't permanently
    // swallow this month's warning (see trial-nurture lesson: only mark
    // "sent" when the send actually succeeded).
    await p.query(`DELETE FROM generic_entities WHERE id = $1 AND entity_type = 'SpendNotice'`,
      [`spendnotice_${companyId}_${usageMonth}_warning`]).catch(() => {});
    throw emailErr;
  }
  console.log(`[Usage] Spend warning ($${mtdSpend.toFixed(2)}) sent to ${company.created_by} for ${company.name}`);
}

// $200 crossed: notify platform super-admins (bell + email), once per month.
async function notifySpendHardStop(companyId, usageMonth, mtdSpend, { sendEmails = true } = {}) {
  const p = getPool();
  const noticeId = `spendnotice_${companyId}_${usageMonth}_hard_stop`;
  const newlyClaimed = await claimSpendNotice(companyId, usageMonth, 'hard_stop', mtdSpend);
  const { rows } = await p.query(
    `SELECT COALESCE(company_name, data->>'company_name', id) AS name, is_deleted
     FROM companies WHERE id = $1`, [companyId]);
  const company = rows[0] || {};
  const companyName = company.name || companyId;
  sendEmails = sendEmails && !shouldSuppressUsageAlertEmails(companyId, company);

  const noticeRes = await p.query(
    `SELECT data FROM generic_entities WHERE id = $1 AND entity_type = 'SpendNotice' LIMIT 1`,
    [noticeId]
  );
  const noticeData = noticeRes.rows[0]?.data || {};
  if (!newlyClaimed && (noticeData.email_sent_at || noticeData.email_suppressed_at)) return;

  const { rows: adminRows } = await p.query(
    `SELECT DISTINCT COALESCE(user_email, email) AS email FROM staff_profiles
     WHERE is_super_admin = true
       AND is_active IS NOT FALSE
       AND COALESCE(user_email, email) IS NOT NULL LIMIT 5`);
  const now = new Date().toISOString();

  // Bells are created only by the first caller that claims the monthly notice.
  // Email delivery can retry separately if the provider was temporarily down.
  for (const { email } of adminRows) {
    if (newlyClaimed) {
      await p.query(
        `INSERT INTO generic_entities (id, entity_type, company_id, data, created_date, updated_date)
         VALUES ($1, 'Notification', 'companysync_master_001', $2, NOW(), NOW())`,
        [generateEntityId('notif'), JSON.stringify({
          user_email: email,
          title: `🛑 Spend cap tripped: ${companyName} ($${mtdSpend.toFixed(2)} MTD)`,
          message: `${companyName} hit the $${AI_SPEND_HARD_CAP_USD}/mo platform AI spend cap and their platform-key AI is now paused for ${usageMonth}. They've been pointed to BYOK setup.`,
          type: 'cost_alert',
          related_entity_type: 'Company',
          related_entity_id: companyId,
          link_url: '/SaaSAdminDashboard?tab=cost',
          is_read: false,
          company_id: 'companysync_master_001',
          created_at: now,
        })]
      );
    }
  }

  if (!sendEmails) {
    await p.query(
      `UPDATE generic_entities
       SET data = data || $2::jsonb, updated_date = NOW()
       WHERE id = $1 AND entity_type = 'SpendNotice'`,
      [noticeId, JSON.stringify({ email_suppressed_at: now })]
    );
    console.log(`[Usage] Hard-stop notice recorded without email for ${companyName} (test/deleted company)`);
    return;
  }

  // Claim a delivery attempt atomically. If the provider is down, a later usage
  // check retries after five minutes instead of either losing the alert forever
  // or sending on every AI request during the outage.
  const deliveryAttemptAt = new Date().toISOString();
  const deliveryClaim = await p.query(
    `UPDATE generic_entities
     SET data = data || $2::jsonb, updated_date = NOW()
     WHERE id = $1 AND entity_type = 'SpendNotice'
       AND data->>'email_sent_at' IS NULL
       AND data->>'email_suppressed_at' IS NULL
       AND (
         data->>'email_attempted_at' IS NULL
         OR (data->>'email_attempted_at')::timestamptz < NOW() - INTERVAL '5 minutes'
       )
     RETURNING id`,
    [noticeId, JSON.stringify({ email_attempted_at: deliveryAttemptAt })]
  );
  if (deliveryClaim.rowCount === 0) return;

  const successfulRecipients = new Set(
    Array.isArray(noticeData.email_recipients_sent) ? noticeData.email_recipients_sent : []
  );
  for (const { email } of adminRows) {
    if (successfulRecipients.has(email)) continue;
    try {
      await functionHandlers.sendEmailWithResend({
        to: email,
        companyId: 'companysync_master_001',
        subject: `🛑 Spend cap tripped: ${companyName} — $${mtdSpend.toFixed(2)} MTD (${usageMonth})`,
        html: `<div style="font-family:sans-serif;max-width:600px;margin:0 auto;padding:20px;">
          <h2 style="color:#dc2626;margin-top:0;">Platform spend cap tripped</h2>
          <p style="color:#374151;"><strong>${companyName}</strong> reached <strong>$${mtdSpend.toFixed(2)}</strong> month-to-date platform AI cost and has been paused at the $${AI_SPEND_HARD_CAP_USD} hard cap for ${usageMonth}.</p>
          <p style="color:#374151;font-size:14px;">Their in-app messaging points them to Settings → API Keys (BYOK) for instant, unlimited reactivation. Consider reaching out to help them set it up.</p>
          <p style="margin-top:24px;"><a href="${getAppUrl()}/SaaSAdminDashboard?tab=cost" style="background:#2563eb;color:white;padding:10px 20px;text-decoration:none;border-radius:6px;display:inline-block;font-size:14px;">View Cost Dashboard →</a></p>
        </div>`,
      });
      successfulRecipients.add(email);
    } catch (emailErr) {
      console.warn(`[Usage] Hard-stop email to ${email} failed; it will retry on the next usage check:`, emailErr.message);
    }
  }

  const allRecipientEmails = adminRows.map(({ email }) => email);
  const allDelivered = allRecipientEmails.length > 0
    && allRecipientEmails.every((email) => successfulRecipients.has(email));
  await p.query(
    `UPDATE generic_entities
     SET data = data || $2::jsonb, updated_date = NOW()
     WHERE id = $1 AND entity_type = 'SpendNotice'`,
    [noticeId, JSON.stringify({
      email_recipients_sent: [...successfulRecipients],
      ...(allDelivered ? {
        email_sent_at: new Date().toISOString(),
        email_recipient_count: successfulRecipients.size,
      } : {}),
    })]
  );
  if (adminRows.length === 0) {
    console.warn(`[Usage] No active super-admin email recipients for hard-stop alert on ${companyName}; it will retry.`);
  }
  console.log(`[Usage] HARD STOP: ${companyName} at $${mtdSpend.toFixed(2)} MTD — platform AI paused for ${usageMonth}`);
}

// Daily limit gate for SMS and email during trial. Fails OPEN on DB errors.
async function checkTrialDailyUsage(companyId, feature, dailyLimit) {
  if (!companyId || companyId === 'companysync_master_001') return { allowed: true };
  try {
    const p = getPool();
    const companyRes = await p.query('SELECT subscription_plan, company_name FROM companies WHERE id = $1', [companyId]);
    const company = companyRes.rows[0];
    if (!company || company.company_name === 'CompanySync') return { allowed: true };
    if ((company.subscription_plan || 'trial') !== 'trial') return { allowed: true };

    const usageDate = new Date().toISOString().slice(0, 10);
    const { rows } = await p.query(
      `SELECT COALESCE(SUM((data->>'units')::numeric), 0) AS used
       FROM generic_entities
       WHERE entity_type = 'SubscriptionUsage' AND company_id = $1
         AND data->>'usage_date' = $2 AND data->>'feature' = $3`,
      [companyId, usageDate, feature]
    );
    const used = Number(rows[0]?.used || 0);
    if (used >= dailyLimit) {
      const label = feature === 'sms' ? 'SMS' : 'email';
      return { allowed: false, used, limit: dailyLimit, error: `Daily ${label} limit reached for your free trial (${dailyLimit} per day). Your limit refreshes tomorrow — or upgrade to remove limits.` };
    }
    return { allowed: true, used, limit: dailyLimit };
  } catch (e) {
    console.error(`[Usage] checkTrialDailyUsage(${feature}) error (failing open):`, e.message);
    return { allowed: true };
  }
}

// Shared gate for paid-model handlers that take no company_id param at all (they're
// only ever called from an already-logged-in app page). Resolves the caller's
// company from their session — never from client input — then applies the same
// checkAIUsage plan-limit gate as every other AI handler.
async function requireGatedCompany(req, feature = 'ai') {
  const authUser = req ? await getUserFromRequest(req) : null;
  if (!authUser?.email) {
    throw new Error('Authentication required.');
  }
  const companyId = authUser.company_id || null;
  if (companyId) {
    const usage = await checkAIUsage(companyId);
    if (!usage.allowed) throw new Error(usage.error);
    logUsageEvent(companyId, feature).catch(() => {});
  }
  return { companyId, authUser };
}

function generateEntityId(prefix = 'ge') {
  return `${prefix}_${Date.now().toString(36)}_${crypto.randomBytes(6).toString('hex')}`;
}

// All in-app alerts are generic entities. Keep this write behind one helper so
// a missing company scope or the legacy notifications table cannot silently
// make an alert disappear from the bell.
async function createBellNotification(pool, {
  companyId,
  userEmail,
  title,
  message,
  type,
  linkUrl,
  relatedEntityType,
  relatedEntityId,
  isRead = false,
} = {}) {
  if (!companyId) throw new Error('Bell notification requires a company id');
  if (!title || !message || !type) throw new Error('Bell notification requires title, message, and type');

  const quietHours = await getNotificationQuietHours(pool, companyId);
  const data = {
    company_id: companyId,
    ...(userEmail ? { user_email: userEmail } : {}),
    title,
    message,
    type,
    link_url: linkUrl || null,
    is_read: Boolean(isRead),
    ...(relatedEntityType ? { related_entity_type: relatedEntityType } : {}),
    ...(relatedEntityId !== undefined && relatedEntityId !== null
      ? { related_entity_id: String(relatedEntityId) }
      : {}),
    ...(quietHours.active ? {
      deferred_until: quietHours.deferredUntil,
      deferred_reason: 'company_notification_quiet_hours',
    } : {}),
  };
  const id = generateEntityId('notif');
  const result = await pool.query(
    `INSERT INTO generic_entities (id, entity_type, company_id, data, created_date, updated_date)
     VALUES ($1, 'Notification', $2, $3::jsonb, NOW(), NOW())
     ON CONFLICT (id, entity_type) DO NOTHING`,
    [id, companyId, JSON.stringify(data)]
  );
  return { id, inserted: result.rowCount > 0 };
}

// ── Lexi double-booking guard ────────────────────────────────────────────────
async function lexiCheckCalendarConflict(pool, companyId, assignedTo, startTime, endTime) {
  if (!assignedTo || !startTime || !endTime) return null;
  const fmt = (t) => { try { return new Date(t).toLocaleString('en-US', { month: 'short', day: 'numeric', hour: 'numeric', minute: '2-digit', hour12: true }); } catch { return String(t); } };
  const { rows } = await pool.query(`
    SELECT id, title, start_time, end_time FROM calendar_events
    WHERE company_id = $1 AND assigned_to = $2
      AND COALESCE(status,'') NOT IN ('cancelled','tentative')
      AND start_time < $4 AND end_time > $3
    LIMIT 1`, [companyId, assignedTo, startTime, endTime]);
  if (rows.length === 0) return null;
  const ev = rows[0];
  return { conflict: true, existing: ev,
    message: `${assignedTo} is already booked for "${ev.title}" from ${fmt(ev.start_time)} to ${fmt(ev.end_time)}.` };
}
async function lexiFindAvailableSlots(pool, companyId, assignedTo, nearTime, durationMs = 3600000, count = 3) {
  const slots = [];
  let cur = new Date(nearTime);
  const m = cur.getMinutes();
  if (m !== 0 && m !== 30) cur.setMinutes(m < 30 ? 30 : 60, 0, 0);
  else cur.setSeconds(0, 0);
  const deadline = new Date(cur.getTime() + 8 * 24 * 60 * 60 * 1000);
  const fmt = (t) => new Date(t).toLocaleString('en-US', { weekday: 'short', month: 'short', day: 'numeric', hour: 'numeric', minute: '2-digit', hour12: true });
  while (slots.length < count && cur < deadline) {
    const hour = cur.getHours();
    if (hour >= 7 && hour < 18) {
      const slotEnd = new Date(cur.getTime() + durationMs);
      const { rows } = await pool.query(`
        SELECT id FROM calendar_events
        WHERE company_id = $1 AND assigned_to = $2
          AND COALESCE(status,'') != 'cancelled'
          AND start_time < $4 AND end_time > $3
        LIMIT 1`, [companyId, assignedTo, cur.toISOString(), slotEnd.toISOString()]);
      if (rows.length === 0) slots.push({ start: cur.toISOString(), end: slotEnd.toISOString(), label: fmt(cur) });
    }
    cur = new Date(cur.getTime() + 30 * 60 * 1000);
  }
  return slots;
}

/**
 * Build a one-line storm-risk summary for Lexi's property briefing.
 * Queries master StormEvent rows within 15 mi / 5 years of the given coords.
 * Returns a human-readable string on findings, or null when there is no data.
 * Never throws — callers catch all errors silently.
 */
async function _lexiStormSummary(pool, lat, lng) {
  const radiusMiles = 15;
  const daysBack = 1825; // 5 years
  const latF = parseFloat(lat), lngF = parseFloat(lng);
  const latDelta = radiusMiles / 69.0;
  const lngDelta = radiusMiles / (69.0 * Math.cos(latF * Math.PI / 180));
  const haversine = `3959 * 2 * ASIN(SQRT(
    POWER(SIN(RADIANS((data->>'latitude')::float - ${latF}) / 2), 2) +
    COS(RADIANS(${latF})) * COS(RADIANS((data->>'latitude')::float)) *
    POWER(SIN(RADIANS((data->>'longitude')::float - ${lngF}) / 2), 2)
  ))`;
  const { rows } = await pool.query(`
    SELECT data->>'event_type' AS event_type,
           (data->>'hail_size_inches')::float AS hail_size_inches,
           (data->>'wind_speed_mph')::float AS wind_speed_mph
    FROM generic_entities
    WHERE entity_type = 'StormEvent'
      AND (data->>'start_time')::timestamp >= NOW() - INTERVAL '${parseInt(daysBack)} days'
      AND data->>'event_type' IN ('hail','high_wind','tornado','thunderstorm')
      AND data->>'latitude' IS NOT NULL AND data->>'latitude' != ''
      AND data->>'longitude' IS NOT NULL AND data->>'longitude' != ''
      AND data->>'has_geometry' IS DISTINCT FROM 'false'
      AND (data->>'latitude')::float BETWEEN ${latF - latDelta} AND ${latF + latDelta}
      AND (data->>'longitude')::float BETWEEN ${lngF - lngDelta} AND ${lngF + lngDelta}
      AND ${haversine} <= ${radiusMiles}
    LIMIT 500
  `);
  if (!rows.length) return null;

  const hailEvents = rows.filter(r => r.event_type === 'hail' && (r.hail_size_inches || 0) >= 1.0);
  const windEvents = rows.filter(r => (r.event_type === 'high_wind' || r.event_type === 'thunderstorm') && (r.wind_speed_mph || 0) >= 55);
  const tornadoCount = rows.filter(r => r.event_type === 'tornado').length;
  const maxHail = hailEvents.length ? Math.max(...hailEvents.map(r => r.hail_size_inches || 0)) : 0;
  const maxWind  = windEvents.length  ? Math.max(...windEvents.map(r => r.wind_speed_mph || 0)) : 0;

  let riskRating = 'LOW';
  if (tornadoCount > 0 || maxHail >= 2.0 || maxWind >= 100) riskRating = 'EXTREME';
  else if (hailEvents.length >= 3 || windEvents.length >= 5 || maxHail >= 1.5) riskRating = 'HIGH';
  else if (hailEvents.length >= 1 || windEvents.length >= 2) riskRating = 'MODERATE';

  if (riskRating === 'LOW' && !hailEvents.length && !windEvents.length && !tornadoCount) return null;

  const icon = riskRating === 'EXTREME' ? '🚨' : riskRating === 'HIGH' ? '⚠️' : 'ℹ️';
  const parts = [];
  if (hailEvents.length) parts.push(`${hailEvents.length} hail event${hailEvents.length !== 1 ? 's' : ''} ≥ 1"`);
  if (windEvents.length) parts.push(`${windEvents.length} high-wind event${windEvents.length !== 1 ? 's' : ''} ≥ 55 mph`);
  if (tornadoCount) parts.push(`${tornadoCount} tornado${tornadoCount !== 1 ? 'es' : ''}`);
  return `${icon} ${parts.join(', ')} within ${radiusMiles} mi in the past 5 years — ${riskRating} storm risk`;
}
