// Renders a video thumbnail card for emails. Email clients can't play video,
// so this renders a branded "play button" card that links directly to the
// hosted MP4 on the app's /uploads/ path (served via object storage).
function videoCard(APP_URL, videoKey, videoTitle, ctaPath, accent = '#1e3a8a') {
  const videoPath = DRIP_VIDEOS[videoKey] || null;
  const appLink = videoPath ? `${APP_URL}${videoPath}` : `${APP_URL}${ctaPath}`;
  const watchLabel = videoPath ? '▶ Watch the video →' : `▶ Watch: ${videoTitle} →`;
  return `
    <div style="margin:20px 0;border-radius:10px;overflow:hidden;border:2px solid #e5e7eb;">
      <a href="${appLink}" style="display:block;text-decoration:none;">
        <div style="background:${accent};padding:32px 24px;text-align:center;position:relative;">
          <div style="display:inline-block;background:rgba(255,255,255,0.18);border-radius:50%;width:64px;height:64px;line-height:64px;font-size:32px;margin-bottom:12px;">▶</div>
          <div style="color:white;font-size:18px;font-weight:bold;line-height:1.3;">${videoTitle}</div>
          <div style="color:rgba(255,255,255,0.8);font-size:13px;margin-top:6px;">~1 min watch · Click to play</div>
        </div>
      </a>
      <div style="background:#f9fafb;padding:14px 20px;text-align:center;">
        <a href="${appLink}" style="color:${accent};font-weight:bold;font-size:14px;text-decoration:none;">${watchLabel}</a>
      </div>
    </div>`;
}

