// Resolves email/phone recipients for platform->owner trial messaging: company
// admins (staff_profiles) first, falling back to the company's own contact info.
async function resolveTrialRecipients(pool, company) {
  const { rows: staff } = await pool.query(
    `SELECT email, user_email, phone, cell_phone FROM staff_profiles WHERE company_id = $1 AND is_administrator = true`,
    [company.id]
  );
  const emails = Array.from(new Set(
    staff.map(s => s.email || s.user_email).filter(Boolean)
      .concat([company.billing_email, company.email].filter(Boolean))
  ));
  const phones = Array.from(new Set(
    staff.map(s => s.cell_phone || s.phone).filter(Boolean)
      .concat([company.phone].filter(Boolean))
  ));
  return { staff, emails, phones };
}

// Returns { attempted, succeeded } so callers can avoid marking a touch as
// "sent" when every delivery failed (a transient Postmark/SES/Twilio outage would
// otherwise permanently skip that day for the company). attempted===0 means
// there was genuinely nothing to send (no template or no recipients).
async function sendTrialDayTouch(company, day, ctx, recipients) {
  let attempted = 0;
  let succeeded = 0;
  const tpl = getTrialEmailTemplate(day, company.company_name || 'there', ctx);
  if (tpl && recipients.emails.length > 0) {
    for (const to of recipients.emails) {
      attempted++;
      try {
         await sendPlatformSubscriberEmail({
           from: PLATFORM_EMAIL_FROM,
           replyTo: PLATFORM_EMAIL_REPLY_TO,
           to,
           subject: tpl.subject,
           html: tpl.html,
           context: { source: 'trial-lifecycle', companyId: company.id },
         });
        succeeded++;
      } catch (e) {
        console.error(`[TrialLifecycle] email to ${to} failed:`, e.message);
      }
    }
  }
  const smsText = getTrialSmsTemplate(day, company.company_name || 'there', ctx);
  if (smsText && recipients.phones.length > 0) {
    for (const to of recipients.phones) {
      attempted++;
      try {
        await functionHandlers.sendSMS({ to, message: smsText });
        succeeded++;
      } catch (e) {
        console.error(`[TrialLifecycle] SMS to ${to} failed:`, e.message);
      }
    }
  }
  return { attempted, succeeded };
}

// Upserts the per-company TrialNurtureLog so re-runs / the Day-0 hook never
// double-send. `daysToMark` should include every touchpoint <= the day just
// sent (prevents a backlog flood if the cron was down for a while).
async function markTrialTouchesSent(pool, companyId, existingSent, daysToMark) {
  const newSent = { ...existingSent };
  for (const d of daysToMark) newSent[`day${d}`] = new Date().toISOString();
  const logId = `trial-nurture-${companyId}`;
  await pool.query(
    `INSERT INTO generic_entities (id, entity_type, company_id, data, created_date, updated_date)
     VALUES ($1, 'TrialNurtureLog', $2, $3, NOW(), NOW())
     ON CONFLICT (id, entity_type) DO UPDATE SET data = EXCLUDED.data, updated_date = NOW()`,
    [logId, companyId, JSON.stringify({ company_id: companyId, sent: newSent })]
  );
}

