function getEncryptionKey() {
  const keyHex = process.env.ENCRYPTION_KEY;
  if (!keyHex) throw new Error('ENCRYPTION_KEY environment variable not set');
  return Buffer.from(keyHex, 'hex');
}

function encryptApiKey(rawKey) {
  if (!rawKey) return null;
  const key = getEncryptionKey();
  const iv = crypto.randomBytes(12);
  const cipher = crypto.createCipheriv('aes-256-gcm', key, iv);
  let encrypted = cipher.update(rawKey, 'utf8', 'hex');
  encrypted += cipher.final('hex');
  const authTag = cipher.getAuthTag().toString('hex');
  return `${iv.toString('hex')}:${authTag}:${encrypted}`;
}

function decryptApiKey(encrypted) {
  if (!encrypted) return null;
  const parts = encrypted.split(':');
  if (parts.length !== 3) throw new Error('Invalid encrypted key format');
  const [ivHex, authTagHex, ciphertext] = parts;
  const key = getEncryptionKey();
  const decipher = crypto.createDecipheriv('aes-256-gcm', key, Buffer.from(ivHex, 'hex'));
  decipher.setAuthTag(Buffer.from(authTagHex, 'hex'));
  let decrypted = decipher.update(ciphertext, 'hex', 'utf8');
  decrypted += decipher.final('utf8');
  return decrypted;
}

function maskApiKey(raw) {
  if (!raw) return '';
  if (raw.length <= 4) return '••••';
  return '••••' + raw.slice(-4);
}

function detectSmtpSettings(email) {
  if (!email || !email.includes('@')) return null;
  const domain = email.split('@')[1].toLowerCase();
  const settings = SMTP_AUTO_DETECT_MAP[domain];
  if (settings) return { ...settings, domain, detected: true };
  return { host: `mail.${domain}`, port: 587, encryption: 'STARTTLS', domain, detected: false, note: 'Auto-guessed settings - please verify' };
}

// Returns { key, isOwn }. isOwn is true ONLY when the company's stored Gemini key
// decrypted successfully and is the key we'll actually use — so the metering
// decision (BYOK = free) can never diverge from the key that was billed. Mirrors
// the getCompanyTwilioConfig pattern.
async function getCompanyGeminiKeyInfo(companyId) {
  const platform = process.env.GOOGLE_GEMINI_API_KEY || null;
  if (!companyId) return { key: platform, isOwn: false };
  try {
    const pool = getPool();
    if (!pool) return { key: platform, isOwn: false };
    const { rows } = await pool.query(
      `SELECT data FROM generic_entities WHERE entity_type = 'CompanyApiKeys' AND company_id = $1 ORDER BY updated_date DESC NULLS LAST LIMIT 1`,
      [companyId]
    );
    const data = rows[0]?.data;
    if (data?.gemini_api_key) {
      const decrypted = decryptApiKey(data.gemini_api_key);
      if (decrypted) return { key: decrypted, isOwn: true };
    }
  } catch (e) { console.error('[BYOK-Dev] getCompanyGeminiKeyInfo error:', e.message); }
  return { key: platform, isOwn: false };
}

async function getCompanyGeminiKey(companyId) {
  return (await getCompanyGeminiKeyInfo(companyId)).key;
}

async function getCompanyTwilioConfig(companyId) {
  const fallback = { accountSid: process.env.TWILIO_ACCOUNT_SID, authToken: process.env.TWILIO_AUTH_TOKEN, phoneNumber: process.env.TWILIO_PHONE_NUMBER, isOwn: false };
  if (!companyId) return fallback;
  try {
    const pool = getPool();
    if (!pool) return fallback;
    const { rows } = await pool.query(
      `SELECT data FROM generic_entities WHERE entity_type = 'CompanyApiKeys' AND company_id = $1 ORDER BY updated_date DESC NULLS LAST LIMIT 1`,
      [companyId]
    );
    const data = rows[0]?.data;
    if (data?.twilio_account_sid && data?.twilio_auth_token && data?.twilio_phone_number) {
      return { accountSid: decryptApiKey(data.twilio_account_sid), authToken: decryptApiKey(data.twilio_auth_token), phoneNumber: data.twilio_phone_number, isOwn: true };
    }
    // Phone-number-only override — keep global SID/token, just swap the from number
    if (data?.twilio_phone_number) {
      return { ...fallback, phoneNumber: data.twilio_phone_number, isOwn: true };
    }
  } catch (e) { console.error('[BYOK-Dev] getCompanyTwilioConfig error:', e.message); }
  return fallback;
}

// Library templates use a few human-friendly trigger names while older entity
// paths emit their operational equivalents. Treat these as aliases at lookup
// time so activating a template does not silently disable it for a real event.
// Keep this compatibility layer here rather than duplicating template rows or
// rewriting existing tenant workflows.
const WORKFLOW_TRIGGER_ALIASES = {
  project_completed: ['project_completed', 'job_completed'],
  job_completed: ['job_completed', 'project_completed'],
  inspection_scheduled: ['inspection_scheduled', 'appointment_created'],
  appointment_created: ['appointment_created', 'inspection_scheduled'],
  inspection_completed: ['inspection_completed', 'appointment_completed'],
  appointment_completed: ['appointment_completed', 'inspection_completed'],
};

function workflowTriggerTypes(triggerType) {
  const normalized = String(triggerType || '').trim();
  return WORKFLOW_TRIGGER_ALIASES[normalized] || [normalized];
}

async function getCompanyEmailConfig(companyId) {
  const fallback = { type: 'resend', apiKey: process.env.RESEND_API_KEY, isOwn: false };
  if (!companyId) return fallback;
  try {
    const pool = getPool();
    if (!pool) return fallback;
    const { rows } = await pool.query(
      `SELECT data FROM generic_entities WHERE entity_type = 'CompanyApiKeys' AND company_id = $1 ORDER BY updated_date DESC NULLS LAST LIMIT 1`,
      [companyId]
    );
    const data = rows[0]?.data;
    const emailMode = data?.email_type || data?.email_mode;
    if (emailMode === 'smtp' && data?.smtp_host && (data?.smtp_username || data?.smtp_email)) {
      return { type: 'smtp', host: data.smtp_host, port: parseInt(data.smtp_port) || 587, secure: data.smtp_encryption === 'SSL', auth: { user: data.smtp_username, pass: data.smtp_password ? decryptApiKey(data.smtp_password) : '' }, from: data.smtp_email || data.smtp_username, isOwn: true };
    }
    if (data?.resend_api_key) return { type: 'resend', apiKey: decryptApiKey(data.resend_api_key), isOwn: true };
  } catch (e) { console.error('[BYOK-Dev] getCompanyEmailConfig error:', e.message); }
  return fallback;
}

function parseCookies(cookieHeader) {
  const cookies = {};
  if (!cookieHeader) return cookies;
  cookieHeader.split(';').forEach(c => {
    const idx = c.indexOf('=');
    if (idx > 0) {
      const key = c.slice(0, idx).trim();
      const val = c.slice(idx + 1).trim();
      try { cookies[key] = decodeURIComponent(val); } catch { cookies[key] = val; }
    }
  });
  return cookies;
}

function unsignCookie(signedValue, secret) {
  if (!signedValue || !signedValue.startsWith('s:')) return null;
  const val = signedValue.slice(2);
  const dotIndex = val.lastIndexOf('.');
  if (dotIndex === -1) return null;
  const sid = val.slice(0, dotIndex);
  const sig = val.slice(dotIndex + 1);
  const expected = crypto.createHmac('sha256', secret).update(sid).digest('base64').replace(/=+$/, '');
  if (sig === expected) return sid;
  return null;
}

async function getUserFromRequest(req) {
  const SESSION_SECRET = process.env.SESSION_SECRET;
  if (!SESSION_SECRET) return null;
  const cookies = parseCookies(req.headers.cookie);
  const signedSid = cookies['connect.sid'];
  if (!signedSid) return null;
  const sid = unsignCookie(signedSid, SESSION_SECRET);
  if (!sid) return null;
  try {
    const p = getPool();
    const result = await p.query('SELECT sess FROM sessions WHERE sid = $1 AND expire > NOW()', [sid]);
    if (result.rows.length > 0) {
      const sess = typeof result.rows[0].sess === 'string' ? JSON.parse(result.rows[0].sess) : result.rows[0].sess;
      // Primary shape: Replit OIDC and local-auth (createSession in local-auth.cjs)
      // both store the email here. Fallbacks cover any alternative session shapes
      // (e.g. a direct sess.user.email or sess.email) so email/password logins
      // are never silently denied by handlers that call getUserFromRequest.
      const email = sess?.passport?.user?.claims?.email
        || sess?.user?.email
        || sess?.email;
      if (email) {
        const userResult = await p.query('SELECT platform_role, company_id FROM users WHERE email = $1', [email]);
        const userRow = userResult.rows[0];
        const platform_role = userRow?.platform_role || null;
        const staffResult = await p.query(
          `SELECT is_super_admin, is_administrator, company_id
           FROM staff_profiles
           WHERE (email = $1 OR user_email = $1)
             AND ($2::text IS NULL OR company_id = $2)
           ORDER BY CASE WHEN company_id = $2 THEN 0 ELSE 1 END, id
           LIMIT 1`,
          [email, userRow?.company_id || null]
        );
        const staffRow = staffResult.rows[0];
        // users.company_id is authoritative; staff_profiles.company_id is a fallback for
        // staff accounts that only exist as a StaffProfile row (no matching users row field).
        const company_id = userRow?.company_id || staffRow?.company_id || null;
        const is_super_admin = staffRow?.is_super_admin === true || platform_role === 'super_admin' || company_id === 'companysync_master_001';
        return { email, platform_role, company_id, is_super_admin, is_administrator: staffRow?.is_administrator === true };
      }
    }
  } catch (e) {
    console.error('[Functions] Session lookup error:', e.message);
  }
  return null;
}

function getAppUrl() {
  // In the Replit dev workspace (not a published deployment), links must point at the
  // workspace's own preview domain — never at production. Data created while testing in
  // dev only exists in the dev database, so a production-domain link would 404 there
  // even though the token/signature checks out. See docs on estimate-link-signing.
  if (process.env.REPLIT_DEPLOYMENT !== '1' && process.env.REPLIT_DEV_DOMAIN) {
    return `https://${process.env.REPLIT_DEV_DOMAIN}`;
  }
  return process.env.VITE_REPLIT_APP_URL || 'https://getcompanysync.com';
}

async function handlePropertyMeasurementRoute(req, res) {
  const pathname = new URL(req.url || '/', 'http://localhost').pathname;
  if (pathname !== '/api/measurements/analyze-photos' && pathname !== '/api/measurements') return false;
  const send = (payload, status = 200) => {
    if (res.headersSent) return;
    res.writeHead(status, { 'Content-Type': 'application/json' });
    res.end(JSON.stringify(payload));
  };
  try {
    const caller = await getUserFromRequest(req);
    if (!caller?.email) {
      send({ error: 'Authentication required' }, 401);
      return true;
    }
    const pool = getPool();
    const isList = pathname === '/api/measurements' && req.method === 'GET';
    if (isList) {
      const query = new URL(req.url, 'http://localhost').searchParams;
      const requestedCompanyId = query.get('company_id');
      const companyId = await resolveMeasurementCompany({
        pool,
        caller,
        requestedCompanyId,
        invoiceId: query.get('invoice_id'),
        jobId: query.get('job_id'),
      });
      const rows = await listPropertyMeasurements({
        pool,
        companyId,
        invoiceId: query.get('invoice_id'),
        jobId: query.get('job_id'),
      });
      send({ measurements: rows });
      return true;
    }
    if (pathname !== '/api/measurements/analyze-photos' || req.method !== 'POST') {
      send({ error: 'Method not allowed' }, 405);
      return true;
    }
    const impersonationContext = await tenantGuard.resolveRequestContext(req, pool);
    if (impersonationContext.isImpersonating) {
      send({ error: 'Photo measurement is blocked during an impersonation session.' }, 403);
      return true;
    }
    const body = JSON.parse(await parseBody(req, 2 * 1024 * 1024));
    const requestedCompanyId = body.company_id || body.companyId || null;
    const companyId = await resolveMeasurementCompany({
      pool,
      caller,
      requestedCompanyId,
      invoiceId: body.invoice_id || body.invoiceId || null,
      jobId: body.job_id || body.jobId || null,
    });
    const { key: apiKey } = await getCompanyGeminiKeyInfo(companyId);
    const requestHost = req.headers['x-forwarded-host'] || req.headers.host;
    const requestBaseUrl = requestHost ? `https://${requestHost}` : getAppUrl();
    const result = await analyzePropertyPhotos({
      pool,
      companyId,
      invoiceId: body.invoice_id || body.invoiceId || null,
      jobId: body.job_id || body.jobId || null,
      photoUrls: body.photo_urls || body.photoUrls,
      requestBaseUrl,
      apiKey,
      checkAIUsage,
      logUsageEvent,
      createdBy: caller.email,
    });
    send({ measurement: result });
  } catch (error) {
    const status = error instanceof PropertyMeasurementError ? error.statusCode : (error instanceof SyntaxError ? 400 : 500);
    console.error('[PropertyMeasurements] request failed:', error.message);
    send({ error: status === 500 ? 'Photo measurement failed. Please try again.' : (status === 400 ? 'Invalid JSON request body.' : error.message), code: error.code }, status);
  }
  return true;
}

