    const spRes = await p.query(
      `SELECT company_id FROM staff_profiles WHERE (user_email = $1 OR email = $1) AND is_administrator = true LIMIT 1`,
      [user.email]
    );
    if (spRes.rows.length === 0) return { error: 'Admin access required' };
    const companyId = spRes.rows[0].company_id;

